import type { SVGProps } from "react";

/**
 * Icon-Set fuer den Equipment-Katalog (Instrumente, PA-Technik, Amps/Pedale),
 * aus KI-generierten Icon-Sheets vektorisiert (Ausgangsbilder nicht Teil des
 * Repos). Jedes Icon ist eine Liste gefuellter Pfade mit eigenem viewBox;
 * Farbe wird ueber fill="currentColor" gesteuert.
 */

type IconProps = SVGProps<SVGSVGElement>;

type IconPath = { d: string; transform?: string };

function Filled({
  viewBox,
  paths,
  ...props
}: IconProps & { viewBox: string; paths: readonly IconPath[] }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={viewBox} fill="currentColor" {...props}>
      {paths.map((p, i) => (
        <path key={i} d={p.d} transform={p.transform} />
      ))}
    </svg>
  );
}

