export const EQUIPMENT_ICONS: Record<EquipmentIconKey, (props: IconProps) => React.ReactElement> =
  Object.fromEntries(
    EQUIPMENT_ICON_GROUPS.flatMap((g) => g.icons).map((i) => [i.key, i.Icon])
  ) as Record<EquipmentIconKey, (props: IconProps) => React.ReactElement>;

export function isEquipmentIconKey(value: string | null | undefined): value is EquipmentIconKey {
  return !!value && value in EQUIPMENT_ICONS;
}

/**
 * Uebersetzt einen Icon-Key (z. B. "guitar-strat") in den camelCase-Schluessel
 * unter dem Namespace "equipment.icons" in den messages/*.json ("guitarStrat").
 */
export function equipmentIconLabelKey(key: EquipmentIconKey): string {
  return key.replace(/-(.)/g, (_, c: string) => c.toUpperCase());
}

